using System.Collections.Immutable;
using System.Text;
using System.Text.RegularExpressions;
using Extensions.Pack;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules.Fixtures
{
    [TestCategory("Coding-Rules Fixtures")]
    // [TestCategory("Basic")]
    [TestClass]
    public class RJIT_CR_BC_C_00002 : MsTestBase
    {
        private sealed record AnalyzedCodeResult(string ErrorClass, string ErrorClassName, string ErrorSyntaxTree);
        private IImmutableList<AnalyzedCodeResult> CodeRule()
        {
            var analyzedCode = (from @class in Classes
                where @class.Modifiers.Contains(Modifier.Static).IsFalse()
                from property in @class.Properties
                where property.IsReadOnly.IsFalse()
                && property.Modifiers.Contains(Modifier.Static).IsFalse() && property.SyntaxTree.Contains("private set;").IsFalse()
                select new AnalyzedCodeResult(@class.FullQualifiedName, @class.Name, $"{string.Join(",",property.SyntaxTree)}")).ToImmutableList();
            return analyzedCode;
        }

        [TestMethod]
        public async Task Should_SelfHealAsync()
        {
            var codeRuleResult = CodeRule();
            foreach (var errors in codeRuleResult)
            {
                var cSharpFiles = Solution.Projects.SelectMany(p => p.CSharpFileInfos).ToList();
                foreach (var allSyntax in cSharpFiles)
                {
                    var codeToAnalyze = await File.ReadAllTextAsync(allSyntax.Value.FullName).ConfigureAwait(false);
                    if (codeToAnalyze.Contains(errors.ErrorClassName))
                    {
                        var pattern = errors.ErrorSyntaxTree;
                        var replacement = errors.ErrorSyntaxTree.Replace("set;", "init;"); 
                        var modifiedContent = Regex.Replace(codeToAnalyze, pattern, replacement);
                        await File.WriteAllTextAsync(allSyntax.Value.FullName, modifiedContent, new UTF8Encoding())
                            .ConfigureAwait(false);
                    }
                }
            }
        }
    }
